const req = $node["webhook-wa-01"].json.body || {};
const record = $node["postgres-fetch-02"].json || {};

const patientName = req.patientName || record.patientName || 'Patient';
const phone = req.recipientPhoneNumber || req.phone || '+918903643218';
const lang = req.language || record.language || 'Tamil';

const textMessage = `🏥 *St. Jude Memorial Hospital - Official Discharge Care Plan*
------------------------------------------------
Hello *${patientName}*, here is your personalized recovery and medication guide in *${lang}*.

🩺 *Diagnosis / நிலை:*
${record.diagnoses || 'பொது மருத்துவ மீட்பு மற்றும் அவதானிப்பு'}

💊 *Prescribed Medications / பரிந்துரைக்கப்பட்ட மருந்துகள்:*
• Post-Discharge Recovery Regimen - தினமும் உணவுக்குப் பிறகு (7 நாட்கள்)
உணவுக்குப் பிறகு தண்ணீருடன் பரிந்துரைக்கப்பட்ட அளவை உட்கொள்ளவும்.

🥗 *Dietary Care / உணவு முறை:*
• நீரேற்றம், ஊட்டச்சத்து நிறைந்த சீரான உணவு
• காரமான அல்லது எண்ணெய் நிறைந்த உணவுகளைத் தவிர்க்கவும்

⚠️ *Emergency Signs / எச்சரிக்கை அறிகுறிகள்:*
காய்ச்சல், மூச்சுத் திணறல் அல்லது அசாதாரண வலி ஏற்பட்டால் உடனடியாக +1 (800) 555-0199 என்ற எண்ணை அழைக்கவும்.

🎙️ *Audio Voice Note Link:*
Listen in ${lang}: https://care.stjudehospital.org/audio/${record.mrn || 'P1008'}`;

return [{
  recipient: phone,
  patientName: patientName,
  whatsappBody: textMessage,
  audioUrl: `https://care.stjudehospital.org/audio/${record.mrn || 'P1008'}.mp3`,
  mrn: record.mrn || req.mrn || 'MRN-P1008',
  channel: req.channel || 'fullPacket'
}];
